def pre(xs):
    if len(xs) > 6:
        return False
    for x in xs:
        if x < -5 or x > 5:
            return False
    return True


def post(xs, result):
    expected = []
    for x in xs:
        seen = False
        for e in expected:
            if e == x:
                seen = True
        if not seen:
            expected.append(x)
    if len(result) != len(expected):
        return False
    for i in range(len(expected)):
        if result[i] != expected[i]:
            return False
    return True
